#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Walks the WalkPath repository owner through the
# one-time GitHub, Cloudflare and secret setup that only a human can do.
# Run: bash scripts/setup-wizard.sh   (re-runnable; skips what it can detect as done)
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: one stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=15
REPO="alterj07/walkpath"
REPO_URL="https://github.com/$REPO"
ENV_FILE="${ENV_FILE:-.env}"   # holds ONLY non-secret values (SITE_URL etc.); gitignored

# Secrets are never written to disk: they are read into memory, verified, handed to
# `gh secret set` when gh is available, and unset. Without gh the wizard opens the
# Settings → Secrets page and you paste the value there yourself.
SECRETS_URL="$REPO_URL/settings/secrets/actions"
VARS_URL="$REPO_URL/settings/variables/actions"

_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# _has_secret NAME: true when gh can see the secret already (skip on re-runs).
_has_secret() {
  _gh_ready || return 1
  gh secret list --repo "$REPO" 2>/dev/null | awk '{print $1}' | grep -qx "$1"
}

# _check_http LABEL URL [curl args...]: 2xx → ✓, else ⚠ (never prints the body).
_check_http() {
  local label="$1" url="$2"; shift 2
  local code
  code=$(curl -sS -o /dev/null -m 15 -w '%{http_code}' "$@" "$url" 2>/dev/null || echo 000)
  if [[ "$code" =~ ^2 ]]; then
    printf '  %s✓ %s verified%s (HTTP %s)\n' "$GREEN" "$label" "$RESET" "$code"; return 0
  fi
  warn "$label did not verify (HTTP $code). Re-check the value; continuing anyway."
  return 1
}

# secret_stage NAME "prompt" "shape regex" [verify-fn]: one secret, end to end.
#   - skips when gh already lists it (unless you choose to replace it)
#   - hidden input, shape check, optional live verification, then gh or manual paste
secret_stage() {
  local name="$1" prompt="$2" shape="$3" verify="${4:-}" value=""
  if _has_secret "$name"; then
    note "$name is already set on GitHub."
    confirm "Replace $name?" || return 0
  fi
  while :; do
    ask_secret "$name" "$prompt (Enter to skip)"
    value="${!name}"
    if [[ -z "$value" ]]; then note "skipped $name"; SKIPPED+=("secret $name (optional)"); return 0; fi
    if [[ -n "$shape" && ! "$value" =~ $shape ]]; then
      warn "that does not look right for $name (expected pattern: $shape)"
      if confirm "Use it anyway?"; then break; fi
      continue
    fi
    break
  done
  if [[ -n "$verify" ]]; then "$verify" "$value" || true; fi
  if _gh_ready; then
    set_secret "$name" "$value"
  else
    open_url "$SECRETS_URL"
    step "New repository secret → Name: $name → paste the value → Add secret."
    SKIPPED+=("confirm GitHub secret $name was pasted at $SECRETS_URL")
    pause "Press Enter once it is saved."
  fi
  unset "$name"; value=""
}

# var_stage NAME "prompt" DEFAULT: a non-secret repository variable (+ local .env copy).
var_stage() {
  local name="$1" prompt="$2" default="$3"
  ask "$name" "$prompt [default: $default]"
  if [[ -z "${!name}" ]]; then printf -v "$name" '%s' "$default"; fi
  write_env "$name" "${!name}"
  if _gh_ready; then
    set_var "$name" "${!name}"
  else
    SKIPPED+=("GitHub variable $name=${!name} at $VARS_URL")
  fi
}

verify_cf_token()  { _check_http "Cloudflare token" "https://api.cloudflare.com/client/v4/user/tokens/verify" -H "Authorization: Bearer $1"; }
verify_mistral()   { _check_http "Mistral key" "https://api.mistral.ai/v1/models" -H "Authorization: Bearer $1"; }
verify_gemini()    { _check_http "Gemini key" "https://generativelanguage.googleapis.com/v1beta/models?pageSize=1" -H "x-goog-api-key: $1"; }
verify_groq()      { _check_http "Groq key" "https://api.groq.com/openai/v1/models" -H "Authorization: Bearer $1"; }
verify_gh_models() { _check_http "GitHub Models token" "https://models.github.ai/catalog/models" -H "Authorization: Bearer $1" -H "Accept: application/vnd.github+json"; }
verify_discord()   { _check_http "Discord webhook" "$1"; }
verify_telegram()  { _check_http "Telegram bot token" "https://api.telegram.org/bot$1/getMe"; }

banner "WalkPath one-time setup"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Preflight: tools and the GitHub CLI (optional)"
say "Checks git, node and curl, and whether the GitHub CLI (gh) is available."
say "With gh, this wizard sets secrets and variables for you; without it, it"
say "opens the right Settings page and waits while you paste."
for t in git node curl; do
  if command -v "$t" >/dev/null 2>&1; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$t"
  else warn "$t is missing; install it before continuing"; fi
done
if ! git remote get-url origin 2>/dev/null | grep -q "$REPO"; then
  warn "run this from a clone of $REPO (origin does not match)"
fi
if _gh_ready; then
  printf '  %s✓%s gh is installed and authenticated\n' "$GREEN" "$RESET"
elif command -v gh >/dev/null 2>&1; then
  warn "gh is installed but not logged in"
  if confirm "Run 'gh auth login' now?"; then gh auth login || true; fi
else
  note "gh is not installed. Optional: https://github.com/cli/cli#installation"
  note "  Fedora: sudo dnf install gh      Debian/Ubuntu: sudo apt install gh      macOS: brew install gh"
  if confirm "Open the install page?"; then open_url "https://github.com/cli/cli#installation"; fi
  pause "Install it now (then 'gh auth login') or press Enter to continue without it."
fi

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Create the empty data branch"
say "The hourly publish job commits JSON shards to a 'data' branch that is never"
say "merged into main. It must exist once, empty and unrelated to main."
if git ls-remote --exit-code --heads origin data >/dev/null 2>&1; then
  printf '  %s✓%s the data branch already exists on origin\n' "$GREEN" "$RESET"
else
  if [[ -n "$(git status --porcelain)" ]]; then
    warn "your working tree has uncommitted changes; commit or set them aside first"
    SKIPPED+=("create the data branch (see docs/github-settings.md §2)")
    pause
  elif confirm "Create and push the orphan 'data' branch now?"; then
    current=$(git rev-parse --abbrev-ref HEAD)
    git switch --orphan data
    git commit --allow-empty -m "chore(data): initialize data branch"
    git push -u origin data
    git switch "$current"
    printf '  %s✓%s data branch created and pushed\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("create the data branch (see docs/github-settings.md §2)")
  fi
fi

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "GitHub: Actions permissions"
say "Why: only allow-listed actions can run, the default token is read-only, and"
say "fork pull requests cannot run workflows until you approve them (plan 11.5)."
open_url "$REPO_URL/settings/actions"
step "Actions permissions → 'Allow alterj07, and select non-alterj07, actions and reusable workflows'."
step "Tick 'Allow actions created by GitHub'; in the allow list enter: actions/*, github/*, ossf/*, cloudflare/*"
step "Workflow permissions → 'Read repository contents and packages permissions'."
step "Untick 'Allow GitHub Actions to create and approve pull requests'."
step "Fork pull request workflows → 'Require approval for all outside collaborators'."
step "Artifact and log retention → 7 days. Save."
pause "Press Enter when saved."

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "GitHub: code security and general settings"
say "Why: secret scanning with push protection, Dependabot and private vulnerability"
say "reporting are free on public repos and the plan's pre-launch checklist requires them."
open_url "$REPO_URL/settings/security_analysis"
step "Dependabot alerts: Enable. Dependabot security updates: Enable."
step "Secret scanning: Enable. Push protection: Enable."
step "Private vulnerability reporting: Enable (SECURITY.md links to it)."
step "Code scanning: leave 'default setup' OFF (codeql.yml already runs CodeQL)."
pause "Press Enter when saved."
open_url "$REPO_URL/settings"
step "Features: untick Wikis and Projects."
step "Pull Requests: allow squash merging only; default message 'Pull request title and description'."
step "Tick 'Automatically delete head branches'."
step "Description: 'Free US tech-internship board, updated hourly.'"
pause "Press Enter when saved."

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "GitHub: branch rulesets for main and data"
say "Why: main changes only through reviewed pull requests with passing checks;"
say "data accepts pushes only from the GitHub Actions app (hourly publish, monthly squash)."
note "Required check names appear in the picker only after each workflow has run once;"
note "add 'check', 'analyze (javascript-typescript)' and 'review' after the first runs."
open_url "$REPO_URL/settings/rules/new?target=branch"
step "Ruleset 'main': Enforcement Active; target branch 'main'."
step "Tick: Restrict deletions; Block force pushes; Require a pull request before merging"
step "      (1 approval, dismiss stale approvals, require review from Code Owners);"
step "      Require status checks to pass (add the three checks once they exist)."
step "Bypass list: add YOURSELF (Repository admin). You are the only code owner, so"
step "      without this GitHub will not let you approve your own pull request."
pause "Press Enter when the main ruleset is saved."
open_url "$REPO_URL/settings/rules/new?target=branch"
step "Ruleset 'data': Enforcement Active; target branch 'data'."
step "Tick: Restrict deletions; Restrict updates (so no human pushes land there)."
step "Bypass list: add the 'GitHub Actions' app with 'Always allow' (the squash job force-pushes)."
step "Do NOT tick 'Block force pushes' on data, or the monthly squash fails. Create."
pause "Press Enter when the data ruleset is saved."

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Cloudflare Pages (SKIP if you deploy on Vercel)"
  say "This project is deployed on Vercel (walkpath.vercel.app), so the Cloudflare Pages steps"
  say "below do not apply. Press Enter to skip. See docs/manual-setup.md sections 4 and 6a."
say "Why: the site is deployed every hour by wrangler to Cloudflare Pages (Direct Upload,"
say "no card, unlimited bandwidth, no CI-build cap)."
open_url "https://dash.cloudflare.com/sign-up"
step "Create a free Cloudflare account (or sign in). No payment method is needed."
pause "Press Enter when signed in."
say "The wizard can create the Pages project with wrangler (opens a browser login)."
PROJECT_DEFAULT=$(_existing CLOUDFLARE_PAGES_PROJECT || echo walkpath)
ask CLOUDFLARE_PAGES_PROJECT "Pages project name [default: $PROJECT_DEFAULT]"
if [[ -z "$CLOUDFLARE_PAGES_PROJECT" ]]; then CLOUDFLARE_PAGES_PROJECT="$PROJECT_DEFAULT"; fi
write_env CLOUDFLARE_PAGES_PROJECT "$CLOUDFLARE_PAGES_PROJECT"
if confirm "Run 'npx wrangler login' and create the project '$CLOUDFLARE_PAGES_PROJECT' now?"; then
  ( cd packages/site && npx --no-install wrangler login ) || warn "wrangler login did not complete"
  if ( cd packages/site && npx --no-install wrangler pages project list 2>/dev/null | grep -q "^\s*$CLOUDFLARE_PAGES_PROJECT\b" ); then
    printf '  %s✓%s Pages project %s already exists\n' "$GREEN" "$RESET" "$CLOUDFLARE_PAGES_PROJECT"
  else
    ( cd packages/site && npx --no-install wrangler pages project create "$CLOUDFLARE_PAGES_PROJECT" --production-branch main ) \
      || warn "could not create the project with wrangler; create it in the dashboard (Workers & Pages → Create → Pages → Direct Upload)"
  fi
else
  open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages/create/pages"
  step "Workers & Pages → Create → Pages → 'Upload assets' (Direct Upload) → name: $CLOUDFLARE_PAGES_PROJECT."
  pause "Press Enter when the project exists."
fi
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Copy the Account ID shown in the right-hand sidebar of Workers & Pages."
secret_stage CLOUDFLARE_ACCOUNT_ID "Paste the Cloudflare account id" '^[0-9a-f]{32}$'

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Cloudflare tokens (SKIP the Pages token on Vercel)"
say "Why: the publish job needs a token that can deploy to this one Pages project and"
say "nothing else; the summarizer fallback needs a separate read-only Workers AI token."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Custom token → Name: walkpath-pages-deploy."
step "Permissions: Account → Cloudflare Pages → Edit. Account Resources: Include → your account only."
step "No zone permissions. Continue → Create Token → copy it (shown once)."
secret_stage CLOUDFLARE_API_TOKEN "Paste the Pages deploy token" '^[A-Za-z0-9_-]{30,}$' verify_cf_token
step "Create a second token → Name: walkpath-workers-ai → Permissions: Account → Workers AI → Read; same account only."
secret_stage CLOUDFLARE_AI_TOKEN "Paste the Workers AI token" '^[A-Za-z0-9_-]{30,}$' verify_cf_token

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "GitHub: repository variables"
say "Why: non-secret settings the workflows read with vars.*: the site URL, the Workday"
say "gate, alert suppression, the logo client id and the Pages project name."
if ! _gh_ready; then open_url "$VARS_URL"; note "Add each variable on this page as the wizard prompts for it."; fi
var_stage SITE_URL "Site URL (no trailing slash)" "https://walkpath.vercel.app"
var_stage WORKDAY_ENABLED "Workday crawl job (now on by default; tested live at 2 s per tenant)" "true"
note "SUPPRESS_ALERTS: leave UNSET. Set it to 'true' for one hour only after a state restore (docs/operations.md)."
say "PUBLIC_BRANDFETCH_CLIENT_ID (optional): company logos. Free at Brandfetch → Developers → Logo Link."
if confirm "Set up Brandfetch logos now?"; then
  open_url "https://developers.brandfetch.com/"
  step "Sign up → Logo Link → copy the client id."
  var_stage PUBLIC_BRANDFETCH_CLIENT_ID "Paste the Brandfetch client id" ""
fi
if _gh_ready; then set_var CLOUDFLARE_PAGES_PROJECT "$CLOUDFLARE_PAGES_PROJECT"; else SKIPPED+=("GitHub variable CLOUDFLARE_PAGES_PROJECT=$CLOUDFLARE_PAGES_PROJECT at $VARS_URL"); fi

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Secrets: LLM providers (summaries)"
say "Why: new internships are summarized through a chain of free tiers; each key is optional"
say "and a missing one just drops that provider from the chain (plan 4.8)."
if ! _gh_ready; then open_url "$SECRETS_URL"; fi
say "1/5 Mistral (primary; Experiment plan, phone verification, 1 req/s, 1B tokens/month)."
open_url "https://console.mistral.ai/api-keys"
step "Choose the free Experiment plan if asked → Create new key → copy."
secret_stage MISTRAL_API_KEY "Paste the Mistral API key" '^[A-Za-z0-9]{20,}$' verify_mistral
say "2/5 Gemini (fallback; AI Studio free tier). Use a dedicated empty Google Cloud project."
open_url "https://aistudio.google.com/apikey"
step "Create API key → in a new project → copy."
secret_stage GEMINI_API_KEY "Paste the Gemini API key" '^AIza[A-Za-z0-9_-]{30,}$' verify_gemini
say "3/5 Workers AI: done in stage 7 (CLOUDFLARE_AI_TOKEN)."
say "4/5 Groq (free tier, small daily budget)."
open_url "https://console.groq.com/keys"
step "Create API Key → copy."
secret_stage GROQ_API_KEY "Paste the Groq API key" '^gsk_[A-Za-z0-9]{20,}$' verify_groq
say "5/5 GitHub Models (150 requests/day). A fine-grained PAT with ONLY the 'Models: Read' account permission."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: walkpath-models; Repository access: none (Public repositories, read-only);"
step "Account permissions → Models → Read-only; expiry 90 days → Generate → copy."
secret_stage GITHUB_MODELS_TOKEN "Paste the GitHub Models token" '^(github_pat_|ghp_)[A-Za-z0-9_]{20,}$' verify_gh_models

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Secrets: SmartRecruiters key and alert channels"
say "Why: SmartRecruiters is polled only as a registered API client (plan 10.2); Discord and"
say "Telegram receive the hourly digest of new internships (plan 2.4). All optional."
if ! _gh_ready; then open_url "$SECRETS_URL"; fi
open_url "https://developers.smartrecruiters.com/"
step "Register a free developer account → create an app → copy the API key (Posting API, read-only)."
secret_stage SMARTRECRUITERS_API_KEY "Paste the SmartRecruiters API key" '^[A-Za-z0-9_-]{16,}$'
say "Discord: in your server, pick the announcements channel."
open_url "https://support.discord.com/hc/en-us/articles/228383668-Intro-to-Webhooks"
step "Channel settings → Integrations → Webhooks → New Webhook → name 'WalkPath' → Copy Webhook URL."
step "Server safety: verification level Medium+, AutoMod for invite links/crypto/'DM me', pinned scam notice (plan 11.7)."
secret_stage DISCORD_WEBHOOK_URL "Paste the Discord webhook URL" '^https://(discord\.com|discordapp\.com)/api/webhooks/[0-9]+/[A-Za-z0-9_-]+$' verify_discord
say "Telegram: a read-only broadcast CHANNEL (not a group), with the bot as admin that can only post."
open_url "https://t.me/BotFather"
step "/newbot → name 'WalkPath Internships' → copy the token."
secret_stage TELEGRAM_BOT_TOKEN "Paste the Telegram bot token" '^[0-9]{6,}:[A-Za-z0-9_-]{30,}$' verify_telegram
step "Create a public channel, add the bot as an admin with 'Post messages' only."
step "The chat id is the channel's @username (e.g. @walkpath_internships) or its numeric id."
secret_stage TELEGRAM_CHAT_ID "Paste the Telegram chat id (@username or -100… number)" '^(@[A-Za-z0-9_]{5,}|-?[0-9]{5,})$'

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Secrets: heartbeat monitor and error reporting"
say "Why: a heartbeat alerts you when no hourly run completes within 90 minutes (plan 7.3);"
say "Sentry captures crawl exceptions. Both free, both optional."
if ! _gh_ready; then open_url "$SECRETS_URL"; fi
open_url "https://betterstack.com/users/sign-up"
step "Uptime → Heartbeats → Create heartbeat → name 'walkpath hourly publish' → period 60 min, grace 30 min → copy the URL."
secret_stage BETTERSTACK_HEARTBEAT_URL "Paste the heartbeat URL" '^https://uptime\.betterstack\.com/api/v[0-9]+/heartbeat/[A-Za-z0-9]+$'
open_url "https://sentry.io/signup/"
step "Developer plan → create a Node.js project 'walkpath-pipeline' → Settings → Client Keys (DSN) → copy."
secret_stage SENTRY_DSN "Paste the Sentry DSN" '^https://[0-9a-f]+@[A-Za-z0-9.-]+/[0-9]+$'

# ── 12 ─────────────────────────────────────────────────────────────────────
stage "Vercel: keep the site updating after each crawl"
say "Why: Vercel rebuilds when main changes, but the hourly run writes job data to the"
say "separate data branch, which does not trigger a rebuild. The hook closes that gap."
open_url "https://vercel.com/dashboard"
step "Project walkpath → Settings → Git → Deploy Hooks → create one for branch 'main'."
step "Also set SITE_URL in Settings → Environment Variables to https://walkpath.vercel.app."
secret_stage VERCEL_DEPLOY_HOOK_URL "Paste the deploy hook URL" '^https://api\.vercel\.com/v[0-9]+/integrations/deploy/'

# ── 13 ─────────────────────────────────────────────────────────────────────
stage "Firebase: optional accounts so saved jobs sync between devices"
say "Why: saved jobs, applied stages, notes and the resume profile live in one browser"
say "until someone signs in. The site works fully without this; the menu just hides."
say "Full walkthrough with the security rules: docs/accounts.md"
open_url "https://console.firebase.google.com"
step "Create a project (free Spark plan, no card)."
step "Authentication → Sign-in method → enable Google, and Email/Password with 'Email link' on."
step "Authentication → Settings → Authorized domains → add walkpath.vercel.app."
step "Firestore Database → create (production mode) → Rules → paste"
step "      packages/site/firebase/firestore.rules → Publish."
step "Project settings → Your apps → Add web app → copy the four values below."
step "These four are PUBLIC by design: they name the project, the rules do the protecting."
if confirm "Set the four Firebase values now?"; then
  var_stage PUBLIC_FIREBASE_API_KEY "Paste apiKey" ""
  var_stage PUBLIC_FIREBASE_AUTH_DOMAIN "Paste authDomain" ""
  var_stage PUBLIC_FIREBASE_PROJECT_ID "Paste projectId" ""
  var_stage PUBLIC_FIREBASE_APP_ID "Paste appId" ""
  note "Set the same four as Environment Variables in Vercel, then redeploy."
else
  SKIPPED+=("Firebase accounts: the four PUBLIC_FIREBASE_* variables (docs/accounts.md)")
fi

# ── 14 ─────────────────────────────────────────────────────────────────────
stage "First run"
say "Trigger the hourly workflow by hand, then watch the data branch and the deployment."
if _gh_ready && confirm "Dispatch the crawl workflow now with gh?"; then
  if gh workflow run crawl.yml --repo "$REPO" -f mode=normal; then printf '  %s✓%s dispatched\n' "$GREEN" "$RESET"; else warn "dispatch failed; use the Actions UI"; fi
  note "Watch it: gh run watch --repo $REPO   (or the Actions tab)"
else
  open_url "$REPO_URL/actions/workflows/crawl.yml"
  step "Run workflow → branch main → mode normal → Run."
fi
SITE_SHOWN="${SITE_URL:-$(_existing SITE_URL || echo 'https://walkpath.pages.dev')}"
say "When the run finishes, check:"
step "$REPO_URL/commits/data  — a 'chore(data): hourly publish' commit appeared."
step "$SITE_SHOWN/status  — 'Updated N min ago', boards polled, jobs open."
step "The run log prints only counts and ids (never bodies or headers)."
step "Then go back to stage 5 and add the three required status checks to the main ruleset."
pause "Press Enter when the first run has been checked."

# ── 15 ─────────────────────────────────────────────────────────────────────
stage "Week-1 experiments (plan 12.3)"
say "Each takes at most half a day; results go into docs/launch-checklist.md."
step "1 Volume census: let the hourly runs go 48 h, then read /status and meta.json for new jobs/day."
step "2 Workday tolerance: node packages/pipeline/scripts/workday-probe.ts  (see docs/workday.md for flags)"
step "    then set the WORKDAY_ENABLED variable to true if no 403s appear at 2 s."
step "3 Header probe: curl -I the five ATS list endpoints for 20 boards; record ETag/Last-Modified (Greenhouse and Lever already send ETags)."
step "4 Timestamp audit: compare first_published/createdAt for 200 Greenhouse and 200 Lever jobs with the hosted page dates."
step "5 LLM quota smoke: dispatch the workflow once with keys set; read meta.json llm counts and pending_summaries."
step "6 Cron reliability: the 'meta' artifact of each run keeps schedule.lateness_min; review after a week."
step "7 Hosting check: confirm no card prompt, that /job/<id> SPA fallback works, and hourly deploys are not counted as builds."
pause "Press Enter to finish."

finish
